pub fn get_empty_v2000_mdb() -> Vec<u8> {
    let mut dec = Vec::with_capacity(98304);
    let mut k = 0;
    while k < EMPTY_MDB_RLE.len() {
        let b = EMPTY_MDB_RLE[k];
        if b == 0xFE {
            let cnt = u16::from_le_bytes([EMPTY_MDB_RLE[k + 1], EMPTY_MDB_RLE[k + 2]]) as usize;
            if cnt > 1 {
                dec.resize(dec.len() + cnt, 0x00);
            } else {
                dec.push(0xFE);
            }
            k += 3;
        } else if b == 0xFD {
            let cnt = u16::from_le_bytes([EMPTY_MDB_RLE[k + 1], EMPTY_MDB_RLE[k + 2]]) as usize;
            if cnt > 1 {
                dec.resize(dec.len() + cnt, 0xFF);
            } else {
                dec.push(0xFD);
            }
            k += 3;
        } else {
            dec.push(b);
            k += 1;
        }
    }
    dec
}
